import math
import random
from typing import List, Tuple

Point = Tuple[int, int, int]
Face = Tuple[int, int, int, int, int, int, int]


def _cross(u: Point, v: Point) -> Point:
    return (
        u[1] * v[2] - u[2] * v[1],
        u[2] * v[0] - u[0] * v[2],
        u[0] * v[1] - u[1] * v[0],
    )


def _dot(u: Point, v: Point) -> int:
    return u[0] * v[0] + u[1] * v[1] + u[2] * v[2]


def _sub(a: Point, b: Point) -> Point:
    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])


def _normal_from_indices(points: List[Point], i: int, j: int, k: int) -> Point:
    a = points[i]
    return _cross(_sub(points[j], a), _sub(points[k], a))


def _plane_gcd_key(normal: Point, point: Point) -> Tuple[int, int, int, int]:
    a, b, c = normal
    g = math.gcd(a, b)
    g = math.gcd(g, c)
    if g:
        a //= g
        b //= g
        c //= g

    if a < 0 or (a == 0 and b < 0) or (a == 0 and b == 0 and c < 0):
        a, b, c = -a, -b, -c

    d = -(a * point[0] + b * point[1] + c * point[2])
    return (a, b, c, d)


def _det3(a: Point, b: Point, c: Point) -> int:
    return _dot(a, _cross(b, c))


def _orientation_ref(points: List[Point], i: int, j: int, k: int, ref4: Point) -> int:
    n = _normal_from_indices(points, i, j, k)
    return _dot(n, _sub(ref4, (4 * points[i][0], 4 * points[i][1], 4 * points[i][2])))


def _oriented_face(points: List[Point], i: int, j: int, k: int, ref4: Point) -> Face:
    if _orientation_ref(points, i, j, k, ref4) > 0:
        i, j, k = i, k, j
    n = _normal_from_indices(points, i, j, k)
    if n == (0, 0, 0):
        return (i, j, k, 0, 0, 0, 0)
    a, b, c = n
    p = points[i]
    const = a * p[0] + b * p[1] + c * p[2]
    return (i, j, k, a, b, c, const)


def _find_initial(points: List[Point]) -> Tuple[int, int, int, int]:
    n = len(points)
    if n < 4:
        raise ValueError("at least 4 distinct non-coplanar points are required")

    i0 = 0
    i1 = -1
    for idx in range(1, n):
        if points[idx] != points[i0]:
            i1 = idx
            break
    if i1 < 0:
        raise ValueError("at least 4 distinct non-coplanar points are required")

    i2 = -1
    for idx in range(n):
        if idx == i0 or idx == i1:
            continue
        if _cross(_sub(points[i1], points[i0]), _sub(points[idx], points[i0])) != (0, 0, 0):
            i2 = idx
            break
    if i2 < 0:
        raise ValueError("all points are collinear")

    i3 = -1
    for idx in range(n):
        if idx == i0 or idx == i1 or idx == i2:
            continue
        if _dot(
            _cross(_sub(points[i1], points[i0]), _sub(points[i2], points[i0])),
            _sub(points[idx], points[i0]),
        ) != 0:
            i3 = idx
            break
    if i3 < 0:
        raise ValueError("all points are coplanar")

    return i0, i1, i2, i3


def _edge_key(u: int, v: int) -> Tuple[int, int]:
    return (u, v) if u < v else (v, u)


def _project(point: Point, drop: int) -> Tuple[int, int]:
    if drop == 0:
        return (point[1], point[2])
    if drop == 1:
        return (point[0], point[2])
    return (point[0], point[1])


def _convex_hull_2d(pts: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if len(pts) < 3:
        return pts
    pts = sorted(set(pts))
    if len(pts) < 3:
        return pts

    lower: List[Tuple[int, int]] = []
    for p in pts:
        while len(lower) >= 2:
            a, b = lower[-2], lower[-1]
            if (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]) <= 0:
                lower.pop()
            else:
                break
        lower.append(p)

    upper: List[Tuple[int, int]] = []
    for p in reversed(pts):
        while len(upper) >= 2:
            a, b = upper[-2], upper[-1]
            if (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]) <= 0:
                upper.pop()
            else:
                break
        upper.append(p)

    return lower[:-1] + upper[:-1]


def _plane_drop(normal: Point) -> int:
    ax, ay, az = abs(normal[0]), abs(normal[1]), abs(normal[2])
    if az >= ax and az >= ay:
        return 2
    if ay >= ax and ay >= az:
        return 1
    return 0


def hull3d(points: List[Point]) -> Tuple[int, int, int]:
    unique: List[Point] = []
    seen = set()
    for p in points:
        if p not in seen:
            seen.add(p)
            unique.append(p)

    if len(unique) < 4:
        raise ValueError("at least 4 distinct non-coplanar points are required")

    rng = random.Random(123456789)
    rng.shuffle(unique)

    pts = unique
    i0, i1, i2, i3 = _find_initial(pts)

    ref4 = (
        pts[i0][0] + pts[i1][0] + pts[i2][0] + pts[i3][0],
        pts[i0][1] + pts[i1][1] + pts[i2][1] + pts[i3][1],
        pts[i0][2] + pts[i1][2] + pts[i2][2] + pts[i3][2],
    )

    faces: List[Face] = [
        _oriented_face(pts, i1, i2, i3, ref4),
        _oriented_face(pts, i0, i3, i2, ref4),
        _oriented_face(pts, i0, i2, i1, ref4),
        _oriented_face(pts, i0, i1, i3, ref4),
    ]
    faces = [f for f in faces if (f[3], f[4], f[5]) != (0, 0, 0)]

    start = 0
    initial = {i0, i1, i2, i3}
    while start < len(pts) and start in initial:
        start += 1

    for idx in range(start, len(pts)):
        p = pts[idx]
        px, py, pz = p

        horizon: dict[Tuple[int, int], Tuple[int, int]] = {}
        visible_count = 0
        kept: List[Face] = []

        for f in faces:
            if f[3] * px + f[4] * py + f[5] * pz - f[6] > 0:
                visible_count += 1
                a, b, c = f[0], f[1], f[2]
                for u, v in ((a, b), (b, c), (c, a)):
                    key = _edge_key(u, v)
                    if key in horizon:
                        del horizon[key]
                    else:
                        horizon[key] = (u, v)
            else:
                kept.append(f)

        if visible_count == 0:
            continue

        new_faces = list(kept)
        for u, v in horizon.values():
            nf = _oriented_face(pts, u, v, idx, ref4)
            if (nf[3], nf[4], nf[5]) != (0, 0, 0):
                new_faces.append(nf)

        if len(new_faces) >= 3:
            faces = new_faces
        else:
            faces = kept

    groups: dict[Tuple[int, int, int, int], List[int]] = {}
    group_normal: dict[Tuple[int, int, int, int], Point] = {}

    for f in faces:
        a, b, c = f[0], f[1], f[2]
        normal = (f[3], f[4], f[5])
        if normal == (0, 0, 0):
            continue
        key = _plane_gcd_key(normal, pts[a])
        if key not in groups:
            groups[key] = []
            group_normal[key] = normal
        groups[key].extend((a, b, c))

    hull_vertices: set[int] = set()
    face_count = 0
    volume6_signed = 0

    for key, members in groups.items():
        members = sorted(set(members))
        if len(members) < 3:
            continue

        outward = group_normal[key]
        canonical = key[:3]
        drop = _plane_drop(canonical)

        proj = [_project(pts[i], drop) for i in members]
        proj_hull = _convex_hull_2d(proj)
        if len(proj_hull) < 3:
            continue

        # Map projected hull points back to original point indices.
        proj_to_idx = {p: i for i, p in zip(members, proj)}
        poly = [proj_to_idx[p] for p in proj_hull]

        # Choose polygon orientation so that it agrees with the outward face normal.
        v0 = pts[poly[0]]
        v1 = pts[poly[1]]
        v2 = pts[poly[2]]
        if _dot(_cross(_sub(v1, v0), _sub(v2, v0)), outward) < 0:
            poly.reverse()

        face_count += 1
        hull_vertices.update(poly)

        a0 = pts[poly[0]]
        for i in range(1, len(poly) - 1):
            bi = pts[poly[i]]
            ci = pts[poly[i + 1]]
            volume6_signed += _det3(a0, bi, ci)

    return (abs(volume6_signed), face_count, len(hull_vertices))
